urlset:

{% for page in static_pages %}

  {{ page.loc }}
  {{ page.lastmod }}
  {{ page.changefreq }}
  {{ page.priority }}

{% endfor %}


{% for post in posts %}

  {{ base_url }}/blog/{{ post.slug }}
  {{ post.updated_at.strftime('%Y-%m-%d') }}
  weekly
  {{ '0.95' if post.is_featured else '0.85' }}

{% endfor %}


{% for cat in categories %}

  {{ base_url }}/blog?category={{ cat.slug }}
  {{ page_lastmod if page_lastmod else '2026-10-01' }}
  weekly
  0.70

{% endfor %}
